ee:message.ee:set-payload:
%dw 2.0
output application/json

var backendStatus = vars.backendStatusCode default 500
var backendBody = payload default {}

---
{
    status: "failed",
    errorCode: backendBody.errorCode default (
        if (backendStatus == 400)
            "INVALID_CUSTOMER_ID"
        else if (backendStatus == 404)
            "CUSTOMER_NOT_FOUND"
        else if (backendStatus == 503)
            "SYSTEM_API_UNAVAILABLE"
        else
            "CUSTOMER_PROFILE_RETRIEVAL_FAILED"
    ),
    message: backendBody.message default (
        if (backendStatus == 400)
            "The supplied customer ID is malformed or invalid."
        else if (backendStatus == 404)
            "Customer profile with ID '" ++
            (vars.customerId default "") ++
            "' does not exist."
        else if (backendStatus == 503)
            "Customer profile service is temporarily unavailable."
        else
            "Unable to retrieve the customer profile."
    ),
    errorDescription:
        backendBody.errorDescription
            default "Customer profile retrieval failed in the Process API.",
    correlationId:
        backendBody.correlationId
            default correlationId
}

%dw 2.0
output application/json
---
{
	"status": "success",
	"message": "Customer orchestration process completed successfully.",
	"data": {
		"accountId": vars.finalAccountId,
		"contactId": vars.finalContactId
	}
}
